import SwiftUI
// Geometry imported from the user-edited Affinity export by scripts/import-trail-art.py.
enum TrailArt {
    enum Asset: String { case kelpForest, sandpit, enemySchool, food, chestMint, chestMintOpen, chestCoral, chestCoralOpen, chestGold, chestGoldOpen }
    private struct Layer { let name:String; let path: Path; let fill: UInt32?; let stroke: UInt32?; let width: Double; let swayGroup: Int; let transform: CGAffineTransform }
    static func draw(_ asset: Asset, in context: GraphicsContext, at point: CGPoint, size: Double, time: Double = 0, spread:Double = 0) {
        var c=context; c.translateBy(x:point.x-size/2,y:point.y-size/2); c.scaleBy(x:size/300,y:size/300)
        if asset == .enemySchool {
            for (i,rig) in enemyRigs.enumerated() {
                drawEnemy(in:c,at:.init(x:rig.bounds.midX,y:rig.bounds.midY),size:rig.bounds.width,index:i,time:time)
            }
            return
        }
        for p in layers[asset] ?? [] {
            var layer = c
            if asset == .kelpForest && p.swayGroup >= 0 {
                let group = Double(p.swayGroup)
                let phase = group * 0.34
                let wave = sin(time / 8000 * .pi * 2 + phase) - sin(phase)
                let ripple = sin(time / 12000 * .pi * 2 + phase) - sin(phase)
                // Each frond, its leaves and veins share a planted root pivot.
                let side=group<2.5 ? -1.0:1.0
                layer.translateBy(x:side*spread*(32+abs(group-2)*5),y:0)
                layer.translateBy(x: 74 + group * 39, y: 247)
                layer.rotate(by: .degrees(wave * 1.25+side*spread*(12+abs(group-2)*3)))
                layer.concatenate(CGAffineTransform(a: 1, b: 0, c: ripple * 0.007, d: 1, tx: 0, ty: 0))
                layer.translateBy(x: -(74 + group * 39), y: -247)
            }
            layer.concatenate(p.transform)
            if let f=p.fill { layer.fill(p.path,with:.color(Color(hex:f))) }
            if let s=p.stroke { layer.stroke(p.path,with:.color(Color(hex:s)),style:.init(lineWidth:p.width,lineCap:.round,lineJoin:.round)) }
        }
    }


    // Reuse the user's exact leaf/stem and fish paths; the editable masters stay intact.
    static func drawFoodStems(in context:GraphicsContext,at point:CGPoint,size:Double) {
        let parts=(layers[.food] ?? []).filter{["stem","left-leaf","left-vein","right-leaf","right-vein"].contains($0.name)}
        drawParts(parts,in:context,at:point,width:size)
    }
    private static func drawParts(_ parts:[Layer],in context:GraphicsContext,at point:CGPoint,width:Double,facing:Double=1) {
        let bounds=parts.reduce(CGRect.null){$0.union($1.path.applying($1.transform).boundingRect)}
        guard !bounds.isNull,bounds.width>0 else{return}
        var c=context;c.translateBy(x:point.x,y:point.y)
        c.scaleBy(x:width/bounds.width*facing,y:width/bounds.width)
        c.translateBy(x:-bounds.midX,y:-bounds.midY)
        for p in parts {
            var layer=c;layer.concatenate(p.transform)
            if let f=p.fill {layer.fill(p.path,with:.color(Color(hex:f)))}
            if let stroke=p.stroke {layer.stroke(p.path,with:.color(Color(hex:stroke)),style:.init(lineWidth:p.width,lineCap:.round,lineJoin:.round))}
        }
    }
    // Rig the official Affinity layers at their real attachments, like PipRenderer.
    // Keep this wrapper above layers: the importer retains it on future art updates.
    private struct EnemyRig {
        let parts:[Layer]
        let bounds:CGRect
        let tail:CGPoint
        let fin:CGPoint
        let dorsal:CGPoint
        let eye:CGPoint
        init(index:Int) {
            let selected=(layers[.enemySchool] ?? []).filter{$0.name.hasPrefix("fish-\(index)-")}
            parts=selected
            let box=selected.reduce(CGRect.null){$0.union($1.path.applying($1.transform).boundingRect)}
            bounds=box
            func part(_ suffix:String)->CGRect {
                guard let p=selected.first(where:{$0.name == "fish-\(index)-\(suffix)"}) else{return box}
                return p.path.applying(p.transform).boundingRect
            }
            let tailBox=part("tail"),finBox=part("side-fin"),top=part("dorsal-fin"),eyeBox=part("eye-white")
            tail = .init(x:tailBox.maxX-2,y:tailBox.midY)
            fin = .init(x:finBox.maxX-1,y:finBox.minY+2)
            dorsal = .init(x:top.midX,y:top.maxY-2)
            eye = .init(x:eyeBox.midX,y:eyeBox.midY)
        }
    }
    private static let enemyRigs=(0..<3).map{EnemyRig(index:$0)}
    private static let enemyBlink:[ReefMotion.Key]=[
        .init(0,0),.init(2830,0),.init(2950,1),.init(2990,1),
        .init(3180,0,arriving:true),.init(6780,0),.init(6900,1),
        .init(6940,1),.init(7130,0,arriving:true),.init(8000,0)
    ]
    static func drawEnemy(in context:GraphicsContext,at point:CGPoint,size:Double,index:Int=0,
                          time:Double=0,moving:Bool=true,facing:Double=1,effort:Double=0) {
        let index=abs(index)%3,rig=enemyRigs[index]
        // All periods divide the shared 48-second ocean loop. Neutral time is exact art.
        let phase=Double(index)*0.23
        func wave(_ period:Double,_ delay:Double=0)->Double {
            guard moving else{return 0}
            return ReefMotion.wave(time-delay,period:period,phase:phase)
                - ReefMotion.wave(-delay,period:period,phase:phase)
        }
        let tailAngle=(7+effort*4)*wave(1600,110)
        let finAngle=9*wave(1200,190)+2*wave(4000)
        let breath=1+0.008*wave(4000)
        let lid=moving ? ReefMotion.track((time+Double(index)*1210).truncatingRemainder(dividingBy:8000),enemyBlink):0
        var fish=context;fish.translateBy(x:point.x,y:point.y)
        fish.rotate(by:.degrees(1.4*wave(4000)))
        fish.scaleBy(x:size/rig.bounds.width*facing/pow(breath,0.6),y:size/rig.bounds.width*breath)
        fish.translateBy(x:-rig.bounds.midX,y:-rig.bounds.midY)
        func pivot(_ c:inout GraphicsContext,_ anchor:CGPoint,_ degrees:Double) {
            c.translateBy(x:anchor.x,y:anchor.y);c.rotate(by:.degrees(degrees));c.translateBy(x:-anchor.x,y:-anchor.y)
        }
        for part in rig.parts {
            var c=fish
            if part.name.hasSuffix("-tail") || part.name.hasSuffix("-tail-lines") {pivot(&c,rig.tail,tailAngle)}
            if part.name.hasSuffix("-side-fin") {pivot(&c,rig.fin,finAngle)}
            if part.name.hasSuffix("-dorsal-fin") {pivot(&c,rig.dorsal,2.5*wave(4000,140))}
            if part.name.contains("-eye-") {
                c.translateBy(x:rig.eye.x,y:rig.eye.y);c.scaleBy(x:1,y:1-lid*0.94);c.translateBy(x:-rig.eye.x,y:-rig.eye.y)
                if !part.name.hasSuffix("-eye-white") {c.translateBy(x:-0.6*wave(8000),y:0)}
            }
            if part.name.hasSuffix("-gill") {c.translateBy(x:0.25*wave(4000),y:0)}
            c.concatenate(part.transform)
            if let f=part.fill {c.fill(part.path,with:.color(Color(hex:f)))}
            if let stroke=part.stroke {c.stroke(part.path,with:.color(Color(hex:stroke)),style:.init(lineWidth:part.width,lineCap:.round,lineJoin:.round))}
        }
    }
    /// Small, separate swimming arcs; fish keep their silhouette instead of
    /// flattening to zero width on a circular orbit. The fins do the swimming.
    static func drawPatrol(in context:GraphicsContext,at point:CGPoint,size:Double,time:Double,moving:Bool,flee:Double=0,direction:Double=1) {
        let anchors=[CGPoint(x:-0.29,y:0.02),CGPoint(x:0.20,y:-0.25),CGPoint(x:0.24,y:0.22)]
        for i in 0..<3 {
            let phase=Double(i)*0.29
            let dx=moving ? ReefMotion.wave(time,period:12000,phase:phase)*0.075:0
            let dy=moving ? ReefMotion.wave(time,period:8000,phase:phase+0.14)*0.045:0
            let p=CGPoint(x:point.x+(anchors[i].x+dx+direction*flee*3)*size,
                          y:point.y+(anchors[i].y+dy-flee*0.8)*size)
            var fish=context;fish.opacity *= 1-flee
            fish.addFilter(.saturation(1.2));fish.addFilter(.brightness(0.035))
            let heading=i == 1 ? -1.0:1.0
            fish.translateBy(x:p.x,y:p.y)
            fish.rotate(by:.degrees(heading == direction ? -12*flee:168*flee))
            drawEnemy(in:fish,at:.zero,size:size*0.54,index:i,time:time,moving:moving,facing:heading,effort:flee)
        }
    }


